import React, { useContext, useEffect, useState } from "react";
import MainLayout from "../layouts/MainLayout";
import { SessionContext } from "../contexts/SessionContext.jsx";
import { supabase } from "../utils/supabase";
import { useNavigate } from "react-router-dom";
import { FaPalette, FaShieldAlt, FaSlidersH } from "react-icons/fa";
import { FiLock, FiRefreshCw } from "react-icons/fi";

const Settings = () => {
	const { session, profile, setProfile } = useContext(SessionContext);
	const navigate = useNavigate();
	const [role, setRole] = useState(null);
	const [newPassword, setNewPassword] = useState("");
	const [confirmPassword, setConfirmPassword] = useState("");

	const effectiveRole = role ?? profile?.role ?? "client";

	useEffect(() => {
		if (!session) {
			navigate("/log-in");
		} else if (session.user.is_anonymous) {
			navigate("/", { replace: true });
		}
	}, [session, navigate]);

	const handleSavePreferences = async (event) => {
		event.preventDefault();

		if (!session?.user?.id) {
			alert("No active session found.");
			return;
		}

		if (profile?.role === "admin" && effectiveRole !== profile.role) {
			const { data, error } = await supabase
				.from("profiles")
				.update({ role: effectiveRole })
				.eq("id", session.user.id)
				.select()
				.single();

			if (error) {
				alert(error.message || error);
				return;
			}

			if (data) {
				setProfile(data);
			}
		}

		alert("Settings saved.");
	};

	const handleResetPreferences = () => {
		setRole(profile?.role ?? "client");
	};

	const handlePasswordChange = async (event) => {
		event.preventDefault();

		if (!newPassword || newPassword.length < 8) {
			alert("New password must be at least 8 characters.");
			return;
		}

		if (newPassword !== confirmPassword) {
			alert("New password and confirm password do not match.");
			return;
		}

		const { error } = await supabase.auth.updateUser({
			password: newPassword,
		});

		if (error) {
			alert(error.message || error);
			return;
		}

		setNewPassword("");
		setConfirmPassword("");
		alert("Password updated.");
	};

	return (
		<MainLayout>
			<div className="min-h-screen bg-base-200 px-3 py-6 sm:px-4 sm:py-10">
				<div className="mx-auto max-w-7xl space-y-6 sm:space-y-10">
					<div>
						<button
							type="button"
							onClick={() => navigate(-1)}
							className="btn btn-black rounded-full"
						>
							Back
						</button>
					</div>

					<div className="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm sm:p-8 md:p-14">
						<div className="flex flex-col gap-10 md:flex-row md:items-end md:justify-between">
							<div className="max-w-2xl">
								<p className="text-sm font-medium uppercase tracking-[0.35em] text-base-content/60">
									Account Settings
								</p>
								<h1 className="mt-4 text-3xl font-semibold leading-tight text-base-content md:text-4xl">
									{profile?.firstname} {profile?.lastname}
								</h1>
								<p className="mt-4 max-w-xl leading-relaxed text-base-content/70">
									Fine-tune the essentials for your account, privacy, and
									security.
								</p>
							</div>
							<div className="grid gap-3 text-sm text-base-content/70 md:text-right">
								<div className="inline-flex items-center gap-2 rounded-full bg-base-200 px-4 py-2">
									<FaSlidersH className="text-base-content/60" />
									<span>1 saved preference</span>
								</div>
								<div className="inline-flex items-center gap-2 rounded-full bg-base-200 px-4 py-2">
									<FiLock className="text-base-content/60" />
									<span>Password controls enabled</span>
								</div>
							</div>
						</div>
					</div>

					<div className="grid min-w-0 gap-5 sm:gap-8 lg:grid-cols-[1.15fr_0.85fr]">
						<form
							onSubmit={handleSavePreferences}
							className="min-w-0 rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm sm:p-8 md:p-12"
						>
							<div className="flex items-center gap-3">
								<div className="flex h-11 w-11 items-center justify-center rounded-full bg-primary/10 text-primary">
									<FaPalette />
								</div>
								<div>
									<h2 className="text-xl font-semibold">Preferences</h2>
									<p className="text-sm text-base-content/60">
										Personalize how the app looks and behaves.
									</p>
								</div>
							</div>

							<div className="mt-7 space-y-5 sm:mt-10 sm:space-y-6">
								{profile?.role === "admin" ? (
									<label className="flex flex-col gap-4 rounded-2xl border border-base-300 px-4 py-4 transition hover:border-base-400 sm:flex-row sm:items-center sm:justify-between sm:px-5 sm:py-5">
										<div className="pr-4">
											<div className="flex items-center gap-2">
												<FaShieldAlt className="text-base-content/60" />
												<span className="block font-medium text-base-content">
													Account role
												</span>
											</div>
											<span className="mt-1 block text-sm text-base-content/60">
												Change your role in the system.
											</span>
										</div>
										<select
										className="select select-bordered select-sm w-full sm:w-36"
											value={effectiveRole}
											onChange={(event) => setRole(event.target.value)}
										>
											<option value="client">Client</option>
											<option value="admin">Admin</option>
										</select>
									</label>
								) : (
									<div className="rounded-2xl border border-base-300 bg-base-50 px-5 py-5">
										<div className="flex items-center gap-2">
											<FaShieldAlt className="text-base-content/60" />
											<span className="block font-medium text-base-content">
												Account role
											</span>
										</div>
										<span className="mt-2 block text-sm text-base-content/60">
											Your role is managed separately by administrators.
										</span>
										<p className="mt-2 text-sm font-semibold text-base-content">
											{profile?.role === "admin" ? "Administrator" : profile?.role === "staff" ? "Staff" : "Client"}
										</p>
									</div>
								)}
							</div>

							<div className="mt-10 border-t border-base-200 pt-6 sm:mt-14 sm:pt-8">
								<div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:gap-5">
									<button
										type="submit"
										className="btn btn-black w-full rounded-full px-6 sm:w-auto"
									>
										Save changes
									</button>
									<button
										type="button"
										onClick={handleResetPreferences}
										className="btn btn-black w-full rounded-full px-6 sm:w-auto"
									>
										Reset defaults
									</button>
								</div>
							</div>
						</form>

						<form
							onSubmit={handlePasswordChange}
							className="min-w-0 rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm sm:p-8 md:p-12"
						>
							<div className="flex items-center gap-3">
								<div className="flex h-11 w-11 items-center justify-center rounded-full bg-secondary/15 text-secondary">
									<FiLock />
								</div>
								<div>
									<h2 className="text-xl font-semibold">Security</h2>
									<p className="text-sm text-base-content/60">
										Update your password and keep your account protected.
									</p>
								</div>
							</div>

							<div className="mt-7 space-y-7 sm:mt-10 sm:ml-4 sm:space-y-10 md:ml-8">
								<label className="form-control max-w-2xl">
									<div className="label">
										<span className="label-text">New password</span>
									</div>
									<input
										type="password"
										className="input input-ghost border-0 border-b border-base-300 rounded-none px-0 pr-3 focus:outline-none focus:border-primary"
										value={newPassword}
										onChange={(event) => setNewPassword(event.target.value)}
										placeholder="Enter new password"
									/>
								</label>

								<label className="form-control max-w-2xl">
									<div className="label">
										<span className="label-text">Confirm new password</span>
									</div>
									<input
										type="password"
										className="input input-ghost border-0 border-b border-base-300 rounded-none px-0 pr-3 focus:outline-none focus:border-primary"
										value={confirmPassword}
										onChange={(event) => setConfirmPassword(event.target.value)}
										placeholder="Confirm new password"
									/>
								</label>

								<div className="rounded-2xl bg-base-200 p-6 text-sm leading-relaxed text-base-content/70">
									Use at least 8 characters and a mix of letters and numbers.
								</div>

								<button
									type="submit"
									className="btn btn-black w-full rounded-full px-6 sm:w-auto"
								>
									Update password
								</button>
							</div>
						</form>
					</div>
				</div>
			</div>
		</MainLayout>
	);
};

export default Settings;
